import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const g=JSON.parse('{"title":"Soundtrack","description":"","frontmatter":{},"headers":[],"relativePath":"demos/SOUNDTRACK.md","filePath":"demos/SOUNDTRACK.md"}'),o={name:"demos/SOUNDTRACK.md"};function l(s,e,i,h,d,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="soundtrack" tabindex="-1">Soundtrack <a class="header-anchor" href="#soundtrack" aria-label="Permalink to &quot;Soundtrack&quot;">​</a></h1><p>The demo songs in the soundtrack style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#angry_shark">Shark Score</a>: <code>angry_shark.yml</code></li><li><a href="#four_wheels_g">Eighties Synth Film Theme</a>: <code>four_wheels_g.yml</code></li><li><a href="#get_the_traps_egon">Spooky Funk Film Theme</a>: <code>get_the_traps_egon.yml</code></li><li><a href="#not_star_trek">Symphonic Space Theme</a>: <code>not_star_trek.yml</code></li><li><a href="#strange_woodworking">Analog-Synth Score</a>: <code>strange_woodworking.yml</code></li><li><a href="#very_large_mammals">Boogie-Woogie Film Tune</a>: <code>very_large_mammals.yml</code></li></ul><p><a id="angry_shark"></a></p><h2 id="shark-score-angry-shark-yml" tabindex="-1">Shark Score: <code>angry_shark.yml</code> <a class="header-anchor" href="#shark-score-angry-shark-yml" aria-label="Permalink to &quot;Shark Score: `angry_shark.yml`&quot;">​</a></h2><p>An orchestral score in the manner of Jaws: two low notes a half step apart, slow at first and faster as the danger comes, the scenes ramping the tempo from 70 to 140 beats a minute and back, with a horn call of its own.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/angry_shark.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/angry_shark.yml</code></a> · E minor · 70 BPM · 3:07 · 7 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">ties</th><th style="text-align:center;">tempo changes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="four_wheels_g"></a></p><h2 id="eighties-synth-film-theme-four-wheels-g-yml" tabindex="-1">Eighties Synth Film Theme: <code>four_wheels_g.yml</code> <a class="header-anchor" href="#eighties-synth-film-theme-four-wheels-g-yml" aria-label="Permalink to &quot;Eighties Synth Film Theme: `four_wheels_g.yml`&quot;">​</a></h2><p>A mid-eighties synth theme in the manner of Axel F, with a hook of its own: a staccato saw lead leaping octaves, a bouncing octave bass in sixteenths, chord stabs and bells.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/four_wheels_g.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/four_wheels_g.yml</code></a> · F minor · 118 BPM · 2:59 · 8 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="get_the_traps_egon"></a></p><h2 id="spooky-funk-film-theme-get-the-traps-egon-yml" tabindex="-1">Spooky Funk Film Theme: <code>get_the_traps_egon.yml</code> <a class="header-anchor" href="#spooky-funk-film-theme-get-the-traps-egon-yml" aria-label="Permalink to &quot;Spooky Funk Film Theme: `get_the_traps_egon.yml`&quot;">​</a></h2><p>A mid-eighties funk-pop film theme in the manner of Ghostbusters, in G mixolydian, with a two-bar synth bass riff, stabs and a brass hook of its own, and a sci-fi wail for the ghosts.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/get_the_traps_egon.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/get_the_traps_egon.yml</code></a> · G mixolydian · 116 BPM · 3:02 · 7 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="not_star_trek"></a></p><h2 id="symphonic-space-theme-not-star-trek-yml" tabindex="-1">Symphonic Space Theme: <code>not_star_trek.yml</code> <a class="header-anchor" href="#symphonic-space-theme-not-star-trek-yml" aria-label="Permalink to &quot;Symphonic Space Theme: `not_star_trek.yml`&quot;">​</a></h2><p>A majestic symphonic theme in the manner of the original Battlestar Galactica&#39;s late-seventies television theme, with a fanfare of its own: horns and trumpets over strings driving in triplets, brass chords, timpani and a march on the snare, the opening and the bridge rising from quiet to full by the scenes&#39; Swell.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/not_star_trek.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/not_star_trek.yml</code></a> · D major · 106 BPM · 3:01 · 6 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">shapes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="strange_woodworking"></a></p><h2 id="analog-synth-score-strange-woodworking-yml" tabindex="-1">Analog-Synth Score: <code>strange_woodworking.yml</code> <a class="header-anchor" href="#analog-synth-score-strange-woodworking-yml" aria-label="Permalink to &quot;Analog-Synth Score: `strange_woodworking.yml`&quot;">​</a></h2><p>A dark synth score in the manner of Survive and John Carpenter: a held chord broken into a pulsing sixteenth-note sequence by an arpeggiator, a deep bass, a halo pad and a slow square lead, with a hat kept to a Euclidean rhythm by its track.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/strange_woodworking.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/strange_woodworking.yml</code></a> · E minor · 100 BPM · 3:02 · 7 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th><th style="text-align:center;">euclid</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="very_large_mammals"></a></p><h2 id="boogie-woogie-film-tune-very-large-mammals-yml" tabindex="-1">Boogie-Woogie Film Tune: <code>very_large_mammals.yml</code> <a class="header-anchor" href="#boogie-woogie-film-tune-very-large-mammals-yml" aria-label="Permalink to &quot;Boogie-Woogie Film Tune: `very_large_mammals.yml`&quot;">​</a></h2><p>A boogie-woogie tune in the manner of Baby Elephant Walk, shuffled by a factory groove: a walking boogie bass through the twelve-bar blues, an organ, horn stabs on a dominant seventh and a calliope with a tune of its own.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/very_large_mammals.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/very_large_mammals.yml</code></a> · F major · 112 BPM · 3:00 · 7 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',33)])])}const y=t(o,[["render",l]]);export{g as __pageData,y as default};
